{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "label_pos",
  "per_column": [
    {
      "name": "explicit_condemnation_language",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Presence of explicit condemnation language is a review-text feature that lies outside the label and plausibly signals negative satisfaction. It is derived from review_text, not from the label itself, and does not require knowing the outcome (label) to observe. Legitimate predictor, though it correlates strongly with sentiment."
    },
    {
      "name": "comparative_dismissal_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Categorizes the type of dismissive comparison (to classics, similar films, genre decline) present in the text. This is a textual signal outside the focus variable and carries plausible predictive signal about negativity without leaking the label."
    },
    {
      "name": "narrative_plot_failure_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Identifies specific narrative/plot complaints (pacing, incoherence, cliche). These are observable text features independent of the label, plausibly predictive of dissatisfaction and adding finer-grained signal than raw text."
    },
    {
      "name": "wasted_potential_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Captures 'wasted potential' complaint subtypes (squandered premise, misused talent). A text-derived criticism feature outside the focus that plausibly predicts negative satisfaction; not a restatement of the label."
    }
  ],
  "n_predictors": 4,
  "predictive_utility": 0.7,
  "rationale": "All four columns are structured, interpretable extractions from review_text that lie outside the focus label and plausibly carry predictive signal about negative satisfaction. None constitutes leakage (they are observable from the text before knowing the label) or a mechanical restatement of the label. They are essentially high-level engineered sentiment/criticism features; because they all encode variants of 'this review contains negative criticism,' they are correlated with each other and somewhat with generic negativity, which caps incremental leverage. Still, the typed categories (comparison, plot failure, wasted potential) provide meaningfully more granular predictive structure than raw text alone, so the set gives good but not exceptional predictive leverage."
}

